const body = $input.first().json;

// Solo procesar cambios de etapa y nuevas oportunidades
const validEvents = ['OpportunityCreate', 'OpportunityUpdate', 'OpportunityStageUpdate'];
if (!validEvents.includes(body.type)) {
  return [{ json: { skip: true, reason: 'event_not_relevant: ' + body.type } }];
}

// GHL puede enviar el contacto en distintos campos según versión
const opp = body.opportunity || body || {};
const contact = opp.contact || body.contact || {};

// Extraer teléfono limpio (quitar +1 para Evolution API)
let phone = (contact.phone || contact.phoneNumber || body.phone || '').replace(/\D/g, '');
if (phone.startsWith('1') && phone.length === 11) phone = phone.slice(1); // quitar +1 EEUU

if (!phone) {
  return [{ json: { skip: true, reason: 'no_phone' } }];
}

const stageName = (opp.stage && opp.stage.name) || opp.stageName || body.stageName || 'Sin etapa';
const firstName = contact.firstName || contact.name || body.firstName || 'Cliente';
const lastName  = contact.lastName || body.lastName || '';
const fullName  = `${firstName} ${lastName}`.trim();
const value     = opp.monetaryValue || opp.value || 0;
const locationId = body.locationId || '';

// Mapeo de etapas → mensajes personalizados
const messages = {
  // Seguros
  'New Lead':              `👋 Hola ${firstName}! Vi que estás buscando opciones de seguro. ¿Tienes 5 minutos para que te explique las mejores coberturas disponibles para ti?`,
  'Contacted':             `Hola ${firstName} 😊 Quería hacer seguimiento a tu consulta de seguros. ¿Pudiste revisar la información que te enviamos?`,
  'Appointment Scheduled': `¡Perfecto ${firstName}! ✅ Tu cita está confirmada. Te enviaré un recordatorio 1 hora antes. Si necesitas reagendar, escríbeme aquí mismo.`,
  'Proposal Sent':         `Hola ${firstName} 📋 Ya te envié la propuesta de seguro a tu correo. ¿La pudiste revisar? Cualquier duda, aquí estoy.`,
  'Follow Up':             `Hola ${firstName} 👋 Solo quería asegurarme de que hayas recibido toda la información. ¿Hay algo en lo que pueda ayudarte hoy?`,
  'Won':                   `¡Felicidades ${firstName}! 🎉 Tu póliza está activa. Recibirás todos los documentos en tu correo. ¡Bienvenido a la familia!`,
  'Lost':                  null, // No enviar mensaje si se perdió
  // Clínicas / Dentistas
  'Cita Agendada':         `Hola ${firstName} 👩‍⚕️ Tu cita está confirmada. Te esperamos. Si necesitas cambiar el horario, responde aquí.`,
  'Cita Completada':       `Gracias por visitarnos ${firstName} 🙏 ¿Cómo te sentiste? Tu opinión nos ayuda a mejorar.`,
  'Seguimiento':           `Hola ${firstName}, ¿cómo te has sentido después de tu última visita? Estamos aquí para cualquier duda.`,
  // Realtor
  'Property Interest':     `Hola ${firstName} 🏠 Vi que estás interesado en propiedades. ¿Te gustaría agendar una visita esta semana?`,
  'Showing Scheduled':     `¡Excelente ${firstName}! 🔑 Tu visita a la propiedad está confirmada. Te envío la dirección y detalles por aquí.`,
  'Offer Made':            `Hola ${firstName} 📝 Tu oferta fue enviada. Estaremos en contacto tan pronto tengamos respuesta.`,
};

const messageText = messages[stageName];

if (messageText === null) {
  return [{ json: { skip: true, reason: 'stage_no_message', stageName } }];
}

return [{
  json: {
    skip: !messageText,
    phone,
    fullName,
    firstName,
    stageName,
    value,
    locationId,
    instance: 'lucy',
    messageText: messageText || `Hola ${firstName}, tenemos novedades sobre tu proceso. ¿Tienes un momento?`,
    eventType: body.type,
    opportunityId: opp.id || body.opportunityId || ''
  }
}];
